namespace sv_a6cc899a7fdb4906b149ec6a3dd1cdd7.Services;

public enum ThemeMode
{
    Light,
    Dark,
    System
}

/// <summary>
/// Scoped service — in Interactive Server mode each circuit gets its own instance,
/// so user theme state is independent per circuit/user.
/// </summary>
public class ThemeService
{
    public ThemeMode Theme { get; private set; } = ThemeMode.System;
    public string AccentColor { get; private set; } = "#6366f1";

    public event Action? OnChange;

    public void SetTheme(ThemeMode theme)
    {
        if (Theme == theme) return;
        Theme = theme;
        NotifyStateChanged();
    }

    public void SetAccentColor(string color)
    {
        if (AccentColor == color) return;
        AccentColor = color;
        NotifyStateChanged();
    }

    public void SetPreferences(ThemeMode theme, string accentColor)
    {
        Theme = theme;
        AccentColor = accentColor;
        NotifyStateChanged();
    }

    private void NotifyStateChanged() => OnChange?.Invoke();
}

@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<span class="theme-indicator" style="color: @ThemeService.AccentColor;" title="Current theme">
    @GetIcon() @ThemeService.Theme
</span>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += StateHasChanged;
    }

    private string GetIcon() => ThemeService.Theme switch
    {
        ThemeMode.Light => "☀️",
        ThemeMode.Dark => "🌙",
        _ => "💻"
    };

    public void Dispose()
    {
        ThemeService.OnChange -= StateHasChanged;
    }
}

@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<button @onclick="CycleTheme" class="theme-toggle" style="color: @ThemeService.AccentColor;">
    @GetIcon()
</button>

@code {
    protected override void OnInitialized()
    {
        ThemeService.OnChange += StateHasChanged;
    }

    private void CycleTheme()
    {
        var next = ThemeService.Theme switch
        {
            ThemeMode.Light => ThemeMode.Dark,
            ThemeMode.Dark => ThemeMode.System,
            _ => ThemeMode.Light
        };
        ThemeService.SetTheme(next);
    }

    private string GetIcon() => ThemeService.Theme switch
    {
        ThemeMode.Light => "☀️",
        ThemeMode.Dark => "🌙",
        _ => "💻"
    };

    public void Dispose()
    {
        ThemeService.OnChange -= StateHasChanged;
    }
}

@page "/settings"
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="settings-panel">
    <div class="setting-group">
        <label>Theme</label>
        <select @bind="selectedTheme" @bind:after="ApplyTheme">
            @foreach (var mode in Enum.GetValues<ThemeMode>())
            {
                <option value="@mode">@mode</option>
            }
        </select>
    </div>

    <div class="setting-group">
        <label>Accent Color</label>
        <input type="color" @bind="selectedColor" @bind:after="ApplyColor" />
        <span style="color: @selectedColor;">@selectedColor</span>
    </div>
</div>

<p>Current: <strong>@ThemeService.Theme</strong> / <strong>@ThemeService.AccentColor</strong></p>

@code {
    private ThemeMode selectedTheme;
    private string selectedColor = "#6366f1";

    protected override void OnInitialized()
    {
        selectedTheme = ThemeService.Theme;
        selectedColor = ThemeService.AccentColor;
        ThemeService.OnChange += OnThemeChanged;
    }

    private void ApplyTheme() => ThemeService.SetTheme(selectedTheme);
    private void ApplyColor() => ThemeService.SetAccentColor(selectedColor);

    private void OnThemeChanged()
    {
        selectedTheme = ThemeService.Theme;
        selectedColor = ThemeService.AccentColor;
        InvokeAsync(StateHasChanged);
    }

    public void Dispose()
    {
        ThemeService.OnChange -= OnThemeChanged;
    }
}

